// Phase 3: Advanced Methods
// ========================================

// IsEmpty returns true if no records match current filters
func (t *Menu) IsEmpty() bool {
	return t.Count() == 0
}

// ModifyAll updates a field for all records matching current filters
// Returns the number of records modified
func (t *Menu) ModifyAll(fieldName string, newValue interface{}) int {
	tableName := MenuTableName
	column, ok := t.columnName(fieldName)
	if !ok {
		fmt.Printf("Error: ModifyAll on unknown field %q of Menu\n", fieldName)
		return 0
	}
	where, args := t.buildWhereClause()

	// Build UPDATE SQL
	updateSQL := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s`, tableName, column, where)

	// Prepend newValue to args
	allArgs := append([]interface{}{newValue}, args...)

	// Convert placeholders for PostgreSQL
	updateSQL = t.convertPlaceholders(updateSQL, len(allArgs))

	result, err := t.db.Exec(updateSQL, allArgs...)
	if err != nil {
		fmt.Printf("Error: Failed to modify all Menu: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

// DeleteAll deletes all records matching current filters
// Returns the number of records deleted
func (t *Menu) DeleteAll() int {
	tableName := MenuTableName
	where, args := t.buildWhereClause()

	// Build DELETE SQL
	deleteSQL := fmt.Sprintf(`DELETE FROM "%s" WHERE %s`, tableName, where)

	// Convert placeholders for PostgreSQL
	deleteSQL = t.convertPlaceholders(deleteSQL, len(args))

	result, err := t.db.Exec(deleteSQL, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete all Menu: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

// CopyFilters copies filters from another record variable
func (t *Menu) CopyFilters(from *Menu) {
	if from.filters == nil {
		t.filters = nil
		return
	}

	// Deep copy filters
	t.filters = make(map[string]*menuFilterCondition)
	for key, filter := range from.filters {
		t.filters[key] = &menuFilterCondition{
			fieldName:    filter.fieldName,
			minValue:     filter.minValue,
			maxValue:     filter.maxValue,
			filterExpr:   filter.filterExpr,
			isExpression: filter.isExpression,
			invalidField: filter.invalidField,
		}
	}

	// Also copy order by fields
	if len(from.orderByFields) > 0 {
		t.orderByFields = make([]string, len(from.orderByFields))
		copy(t.orderByFields, from.orderByFields)
	} else {
		t.orderByFields = nil
	}
}

// GetFilters returns a string representation of current filters
// Useful for debugging and logging
func (t *Menu) GetFilters() string {
	if len(t.filters) == 0 {
		return ""
	}

	var parts []string
	for _, filter := range t.filters {
		if filter.invalidField {
			parts = append(parts, "<invalid field>")
		} else if filter.isExpression {
			parts = append(parts, fmt.Sprintf("%s: %s", filter.fieldName, filter.filterExpr))
		} else if filter.minValue != nil && filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: %v..%v", filter.fieldName, filter.minValue, filter.maxValue))
		} else if filter.minValue != nil {
			parts = append(parts, fmt.Sprintf("%s: >=%v", filter.fieldName, filter.minValue))
		} else if filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: <=%v", filter.fieldName, filter.maxValue))
		}
	}

	return strings.Join(parts, ", ")
}

// ========================================
// Field Validation
// ========================================

// ValidateField validates a field and calls its OnValidate trigger
// This is equivalent to the VALIDATE function
// Usage: customer.ValidateField("Payment_terms_code", types.NewCode("30DAYS"))
func (t *Menu) ValidateField(fieldName string, value interface{}) error {
	fieldNameLower := strings.ToLower(fieldName)

	switch fieldNameLower {
	case "code":
		// Set field value
		if v, ok := value.(types.Code); ok {
			t.Code = v
		} else if v, ok := value.(string); ok {
			t.Code = types.NewCode(v)
		} else {
			return fmt.Errorf("invalid type for field code")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(MenuOnValidate_Code); ok {
				if err := trg.OnValidate_Code(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "description":
		// Set field value
		if v, ok := value.(types.Text); ok {
			t.Description = v
		} else if v, ok := value.(string); ok {
			t.Description = types.NewText(v)
		} else {
			return fmt.Errorf("invalid type for field description")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(MenuOnValidate_Description); ok {
				if err := trg.OnValidate_Description(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "filename":
		// Set field value
		if v, ok := value.(types.Text); ok {
			t.Filename = v
		} else if v, ok := value.(string); ok {
			t.Filename = types.NewText(v)
		} else {
			return fmt.Errorf("invalid type for field filename")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(MenuOnValidate_Filename); ok {
				if err := trg.OnValidate_Filename(t); err != nil {
					return err
				}
			}
		}
		return nil
	}

	return fmt.Errorf("field '%s' not found", fieldName)
}

